function uniqueBy(items, keyOf) {
  const seen = new Set();
  return items.filter((item) => {
    const key = keyOf(item);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

module.exports = { uniqueBy };

const { test } = require("node:test");
const assert = require("node:assert/strict");
const { uniqueBy } = require("../src/solution.cjs");

const byId = (item) => item.id;

test("keeps the first item for each duplicate key, in input order", () => {
  const items = [
    { id: 2, n: "a" },
    { id: 1, n: "b" },
    { id: 2, n: "c" },
    { id: 3, n: "d" },
    { id: 1, n: "e" },
  ];
  assert.deepEqual(uniqueBy(items, byId), [
    { id: 2, n: "a" },
    { id: 1, n: "b" },
    { id: 3, n: "d" },
  ]);
});

test("treats number 1 and string \"1\" as different keys", () => {
  const items = [1, "1", 1, "1"];
  assert.deepEqual(uniqueBy(items, (x) => x), [1, "1"]);
});

test("handles mixed key types without collapsing them", () => {
  const items = [
    { k: 1, v: "num" },
    { k: "1", v: "str" },
    { k: 0, v: "zero" },
    { k: "", v: "empty" },
    { k: "0", v: "zero-str" },
    { k: 1, v: "num-dup" },
  ];
  assert.deepEqual(uniqueBy(items, (x) => x.k).map((x) => x.v), [
    "num",
    "str",
    "zero",
    "empty",
    "zero-str",
  ]);
});

test("returns [] for empty input", () => {
  assert.deepEqual(uniqueBy([], byId), []);
});

test("treats \"__proto__\" as an ordinary key", () => {
  const items = [{ id: "__proto__" }, { id: "constructor" }, { id: "__proto__" }];
  assert.deepEqual(uniqueBy(items, byId), [{ id: "__proto__" }, { id: "constructor" }]);
});

test("does not mutate the input array or return it", () => {
  const items = [1, 1, 2];
  const snapshot = [...items];
  const result = uniqueBy(items, (x) => x);
  assert.deepEqual(items, snapshot);
  assert.notEqual(result, items);
  assert.deepEqual(result, [1, 2]);
});

function uniqueBy(items, keyOf) {
  const seen = new Set();
  const result = [];
  for (const item of items) {
    const key = keyOf(item);
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(item);
  }
  return result;
}

