import re

_PORT_PATTERN = re.compile(r" *([0-9]+) *")


def parse_port(text):
    if not isinstance(text, str):
        raise ValueError(f"port must be a string, got {type(text).__name__}")
    match = _PORT_PATTERN.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid port: {text!r}")
    digits = match.group(1).lstrip("0")
    if not 0 < len(digits) <= 5 or int(digits) > 65535:
        raise ValueError(f"port out of range 1-65535: {text!r}")
    return int(digits)

import sys
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "src"))

from solution import parse_port


class ParsePortTests(unittest.TestCase):
    def test_boundaries(self):
        self.assertEqual(parse_port("1"), 1)
        self.assertEqual(parse_port("65535"), 65535)
        self.assertEqual(parse_port("80"), 80)

    def test_rejects_just_outside_range(self):
        for text in ["0", "65536", "99999", "100000"]:
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_port(text)

    def test_leading_zeros_and_spaces(self):
        self.assertEqual(parse_port("0080"), 80)
        self.assertEqual(parse_port("00000000000000000000065535"), 65535)
