from solution import merge_intervals


class MergeIntervalsTest(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(merge_intervals([]), [])

    def test_single(self):
        self.assertEqual(merge_intervals([[2, 7]]), [[2, 7]])

    def test_touching_endpoints_merge(self):
        self.assertEqual(merge_intervals([[1, 3], [3, 5]]), [[1, 5]])

    def test_gap_does_not_merge(self):
        self.assertEqual(merge_intervals([[1, 3], [4, 5]]), [[1, 3], [4, 5]])

    def test_unsorted_input(self):
        self.assertEqual(
            merge_intervals([[8, 10], [1, 3], [2, 6], [15, 18]]),
            [[1, 6], [8, 10], [15, 18]],
        )

    def test_containment(self):
        self.assertEqual(merge_intervals([[1, 10], [2, 3], [4, 5]]), [[1, 10]])

    def test_nested_inside_later_outer(self):
        self.assertEqual(merge_intervals([[2, 3], [1, 10]]), [[1, 10]])

    def test_duplicates(self):
        self.assertEqual(merge_intervals([[1, 2], [1, 2], [1, 2]]), [[1, 2]])

    def test_same_start_different_ends(self):
        self.assertEqual(merge_intervals([[1, 5], [1, 3]]), [[1, 5]])

    def test_negative_coordinates(self):
        self.assertEqual(
            merge_intervals([[-5, -1], [-3, 2], [4, 6], [-10, -9]]),
            [[-10, -9], [-5, 2], [4, 6]],
        )

    def test_zero_length_interval(self):
        self.assertEqual(merge_intervals([[4, 4], [4, 6]]), [[4, 6]])
        self.assertEqual(merge_intervals([[4, 4], [5, 5]]), [[4, 4], [5, 5]])

    def test_input_not_mutated(self):
        data = [[8, 10], [1, 3], [2, 6]]
        original = copy.deepcopy(data)
        merge_intervals(data)
        self.assertEqual(data, original)

    def test_output_does_not_alias_input(self):
        data = [[1, 3], [5, 7]]
        result = merge_intervals(data)
        result[0][1] = 99
        self.assertEqual(data, [[1, 3], [5, 7]])


