    def test_single_interval(self):
        self.assertEqual(merge_intervals([[2, 7]]), [[2, 7]])

    def test_zero_length_interval(self):
        self.assertEqual(merge_intervals([[4, 4]]), [[4, 4]])

    def test_touching_endpoints_merge(self):
        self.assertEqual(merge_intervals([[1, 3], [3, 5]]), [[1, 5]])

    def test_gap_does_not_merge(self):
        self.assertEqual(merge_intervals([[1, 3], [4, 5]]), [[1, 3], [4, 5]])

    def test_unsorted_input(self):
        self.assertEqual(
            merge_intervals([[8, 10], [1, 3], [2, 6], [15, 18]]),
            [[1, 6], [8, 10], [15, 18]],
        )

    def test_containment(self):
        self.assertEqual(merge_intervals([[1, 10], [2, 3], [4, 5]]), [[1, 10]])

    def test_containment_order_reversed(self):
        self.assertEqual(merge_intervals([[2, 3], [1, 10]]), [[1, 10]])

    def test_duplicates(self):
        self.assertEqual(merge_intervals([[1, 4], [1, 4], [1, 4]]), [[1, 4]])

    def test_chain_of_touching_intervals(self):
        self.assertEqual(merge_intervals([[3, 4], [1, 2], [2, 3]]), [[1, 4]])

    def test_negative_coordinates(self):
        self.assertEqual(
            merge_intervals([[-5, -3], [-10, -8], [-4, 0], [2, 3]]),
            [[-10, -8], [-5, 0], [2, 3]],
        )

    def test_negative_touching_at_zero(self):
        self.assertEqual(merge_intervals([[-3, 0], [-7, -3]]), [[-7, 0]])

    def test_identical_zero_length_intervals(self):
        self.assertEqual(merge_intervals([[0, 0], [0, 0]]), [[0, 0]])

    def test_tuple_pairs_accepted(self):
        self.assertEqual(merge_intervals([(1, 2), (2, 4)]), [[1, 4]])

    def test_input_is_not_mutated(self):
        intervals = [[5, 9], [1, 3], [2, 6], [7, 7]]
        snapshot = copy.deepcopy(intervals)
        merge_intervals(intervals)
        self.assertEqual(intervals, snapshot)

    def test_nested_pairs_are_not_mutated(self):
        inner = [1, 10]
        intervals = [inner, [2, 3]]
        merge_intervals(intervals)
        self.assertEqual(inner, [1, 10])
        self.assertEqual(intervals, [[1, 10], [2, 3]])

    def test_output_does_not_alias_input(self):
        inner = [1, 2]
        result = merge_intervals([inner])
        result[0][1] = 99
        self.assertEqual(inner, [1, 2])


