def merge_intervals(intervals):
    """Merge closed integer intervals; return sorted, non-overlapping [start, end] pairs.

    Runs in O(n log n) time due to sorting and O(n) extra space. The input list
    and its pairs are not modified; the result contains freshly created lists.
    """
    merged = []
    for start, end in sorted(intervals):
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged

