        self.assertEqual(merge_intervals([[1, 3], [3, 3]]), [[1, 3]])

    def test_negative_coordinates(self):
        self.assertEqual(
            merge_intervals([[-5, -1], [-3, 0], [-10, -8]]),
            [[-10, -8], [-5, 0]],
        )

    def test_spanning_zero(self):
        self.assertEqual(merge_intervals([[-2, 2], [1, 5], [-7, -6]]), [[-7, -6], [-2, 5]])

    def test_input_is_not_modified(self):
        intervals = [[8, 10], [1, 3], [2, 6]]
        snapshot = [pair[:] for pair in intervals]
        merge_intervals(intervals)
        self.assertEqual(intervals, snapshot)

    def test_nested_pairs_are_not_modified(self):
        outer = [1, 10]
        inner = [2, 3]
        intervals = [outer, inner]
        result = merge_intervals(intervals)
        self.assertEqual(result, [[1, 10]])
        self.assertEqual(outer, [1, 10])
        self.assertEqual(inner, [2, 3])
        self.assertIs(intervals[0], outer)
        self.assertIsNot(result[0], outer)

