        single = [4, 9]
        result = merge_intervals([single])
        result[0][1] = 100
        self.assertEqual(single, [4, 9])

    def test_tuple_input_pairs(self):
        self.assertEqual(merge_intervals([(5, 6), (1, 2), (2, 4)]), [[1, 4], [5, 6]])

    def test_matches_brute_force_on_random_inputs(self):
