def _brute_force_merge(intervals):
    if not intervals:
        return []
    points = set()
    for a, b in intervals:
        points.update(range(a, b + 1))
    result = []
    for p in sorted(points):
        if result and p == result[-1][1] + 1:
            result[-1][1] = p
        else:
            result.append([p, p])
    return result


