def _brute_force_merge(intervals):
    # Doubling coordinates makes the half-unit gap between [1,3] and [4,5] visible.
    points = set()
    for a, b in intervals:
        points.update(range(2 * a, 2 * b + 1))
    runs = []
    for p in sorted(points):
        if runs and p == runs[-1][1] + 1:
            runs[-1][1] = p
        else:
            runs.append([p, p])
    return [[lo // 2, hi // 2] for lo, hi in runs]

