def naive_merge(intervals):
    pairs = [list(p) for p in intervals]
    changed = True
    while changed:
        changed = False
        for i in range(len(pairs)):
            for j in range(i + 1, len(pairs)):
                a, b = pairs[i], pairs[j]
                if a[0] <= b[1] and b[0] <= a[1]:
                    pairs[i] = [min(a[0], b[0]), max(a[1], b[1])]
                    del pairs[j]
                    changed = True
                    break
            if changed:
                break
    return sorted(pairs)


