class TTLCache {
  #now;
  #entries = new Map();

  constructor(now) {
    this.#now = now;
  }

  set(key, value, ttlMs) {
    if (typeof ttlMs !== 'number' || !Number.isFinite(ttlMs) || ttlMs < 0) {
      throw new RangeError('ttlMs must be a nonnegative finite number');
    }
    this.#entries.set(key, { value, expiresAt: this.#now() + ttlMs });
  }

  get(key) {
    const entry = this.#entries.get(key);
    if (entry === undefined) return undefined;
    if (this.#now() >= entry.expiresAt) {
      this.#entries.delete(key);
      return undefined;
    }
    return entry.value;
  }
}

module.exports = { TTLCache };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { TTLCache } = require('../src/solution.cjs');

function fakeClock(start = 0) {
  let t = start;
  return { now: () => t, advance: (ms) => { t += ms; } };
}

test('returns value before expiry and undefined at the expiry instant', () => {
  const clock = fakeClock();
  const cache = new TTLCache(clock.now);
  cache.set('a', 'v', 100);

  clock.advance(99);
  assert.equal(cache.get('a'), 'v');

  clock.advance(1);
