}

function failingTimes(n, value) {
  let calls = 0;
  const errors = [];
  const operation = async () => {
    calls++;
    if (calls <= n) {
      const error = new Error(`fail ${calls}`);
      errors.push(error);
      throw error;
    }
    return value;
  };
  return { operation, errors, count: () => calls };
}

