});

test('stops immediately when shouldRetry returns false', async () => {
  const { sleep, calls } = fakeSleep();
  const op = failingTimes(5, 'never');
  const seen = [];
  const shouldRetry = (error) => { seen.push(error); return false; };
  await assert.rejects(retry(op.operation, { attempts: 5, delayMs: 5, sleep, shouldRetry }), op.errors[0]);
