function fakeSleep() {
  const calls = [];
  const sleep = async (ms) => {
    calls.push(ms);
  };
  return { sleep, calls };
}

function failingTimes(count, error) {
  let calls = 0;
  const operation = async () => {
    calls += 1;
    if (calls <= count) throw error;
    return `ok after ${calls}`;
  };
  return { operation, getCalls: () => calls };
}

test('returns the first successful value without sleeping', async () => {
  const { sleep, calls } = fakeSleep();
  let invocations = 0;
  const value = await retry(
    async () => {
      invocations += 1;
      return 'done';
    },
    { attempts: 3, delayMs: 50, sleep },
  );
  assert.equal(value, 'done');
  assert.equal(invocations, 1);
  assert.deepEqual(calls, []);
});

test('retries until success and sleeps only between attempts', async () => {
  const { sleep, calls } = fakeSleep();
  const { operation, getCalls } = failingTimes(2, new Error('boom'));
  const value = await retry(operation, { attempts: 5, delayMs: 25, sleep });
  assert.equal(value, 'ok after 3');
  assert.equal(getCalls(), 3);
  assert.deepEqual(calls, [25, 25]);
});

test('throws the last error object unchanged after exhaustion', async () => {
  const { sleep, calls } = fakeSleep();
  const errors = [new Error('first'), new Error('second'), new Error('third')];
  let index = 0;
  const operation = async () => {
    const error = errors[index];
    index += 1;
    throw error;
  };
  await assert.rejects(
    retry(operation, { attempts: 3, delayMs: 10, sleep }),
    (error) => error === errors[2],
  );
  assert.equal(index, 3);
  assert.deepEqual(calls, [10, 10]);
});

test('does not sleep after the final failed attempt', async () => {
  const { sleep, calls } = fakeSleep();
  const { operation } = failingTimes(10, new Error('always'));
  await assert.rejects(retry(operation, { attempts: 1, delayMs: 100, sleep }));
  assert.deepEqual(calls, []);
});

test('stops immediately when shouldRetry returns false', async () => {
  const { sleep, calls } = fakeSleep();
