  await assert.rejects(
    retry(
      async () => {
        invocations += 1;
        throw fatal;
      },
      {
        attempts: 5,
        delayMs: 10,
        sleep,
        shouldRetry: (error) => {
          seen.push(error);
          return false;
        },
      },
    ),
    (error) => error === fatal,
  );
  assert.equal(invocations, 1);
  assert.deepEqual(seen, [fatal]);
  assert.deepEqual(calls, []);
});

test('retries only errors accepted by shouldRetry', async () => {
  const { sleep, calls } = fakeSleep();
  const transient = new Error('transient');
  const permanent = new Error('permanent');
  const outcomes = [transient, transient, permanent];
  let invocations = 0;
  await assert.rejects(
    retry(
      async () => {
