  );
  assert.equal(invocations, 3);
  assert.deepEqual(calls, [5, 5]);
});

test('retries synchronous throws from the operation', async () => {
  const { sleep, calls } = fakeSleep();
  let invocations = 0;
  const value = await retry(
    () => {
      invocations += 1;
      if (invocations < 2) throw new Error('sync');
      return 'sync ok';
    },
    { attempts: 2, delayMs: 7, sleep },
  );
  assert.equal(value, 'sync ok');
  assert.deepEqual(calls, [7]);
});

test('attempts of 1 calls once and never sleeps', async () => {
  const { sleep, calls } = fakeSleep();
  const error = new Error('once');
  let invocations = 0;
  await assert.rejects(
    retry(
      async () => {
        invocations += 1;
        throw error;
      },
      { attempts: 1, delayMs: 3, sleep },
    ),
    (thrown) => thrown === error,
  );
  assert.equal(invocations, 1);
  assert.deepEqual(calls, []);
