test('rejects invalid attempts with RangeError without calling operation', async () => {
  const invalid = [0, -1, 1.5, NaN, Infinity, '3', null, undefined];
  for (const attempts of invalid) {
    let invoked = false;
    await assert.rejects(
      retry(
        async () => {
          invoked = true;
        },
        { attempts, delayMs: 0, sleep: async () => {} },
      ),
      RangeError,
      `attempts=${String(attempts)}`,
    );
    assert.equal(invoked, false);
  }
});

