import csv
import io


def read_people(text):
    try:
        rows = csv.reader(io.StringIO(text, newline=""), strict=True)
        header = next(rows, None)
        if header != ["name", "age"]:
            raise ValueError(f"expected header name,age, got {header!r}")
        people = []
        for row in rows:
            if len(row) != 2:
                raise ValueError(f"expected 2 columns, got {len(row)}: {row!r}")
            name, age = row
            if not (age.isascii() and age.isdigit()) or int(age) > 130:
                raise ValueError(f"invalid age: {age!r}")
            people.append({"name": name, "age": int(age)})
        return people
    except csv.Error as e:
        raise ValueError(str(e)) from e

