import csv
import io
import re

_HEADER = ["name", "age"]
_AGE_PATTERN = re.compile(r"[0-9]+")
_MAX_AGE = 130


def read_people(text):
    reader = csv.reader(io.StringIO(text, newline=""), strict=True)
    try:
        header = next(reader, None)
        if header != _HEADER:
            raise ValueError(f"expected header {_HEADER!r}, got {header!r}")
        people = []
        for row in reader:
            if len(row) != 2:
                raise ValueError(f"expected 2 columns, got {len(row)}: {row!r}")
            name, age_text = row
            people.append({"name": name, "age": _parse_age(age_text)})
    except csv.Error as exc:
        raise ValueError(f"invalid CSV: {exc}") from exc
    return people


def _parse_age(text):
    if not _AGE_PATTERN.fullmatch(text):
        raise ValueError(f"invalid age: {text!r}")
    age = int(text)
    if age > _MAX_AGE:
        raise ValueError(f"age out of range: {text!r}")
    return age

