function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function assertSafeKeys(value) {
  if (Array.isArray(value)) {
    value.forEach(assertSafeKeys);
  } else if (isPlainObject(value)) {
    for (const key of Object.keys(value)) {
      if (UNSAFE_KEYS.has(key)) throw new Error(`Unsafe key in config: ${key}`);
      assertSafeKeys(value[key]);
    }
  }
}

function clone(value) {
  if (Array.isArray(value)) return value.map(clone);
  if (isPlainObject(value)) {
    const out = {};
    for (const key of Object.keys(value)) out[key] = clone(value[key]);
    return out;
  }
  return value;
}

function merge(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) return clone(override);
  const out = clone(base);
  for (const key of Object.keys(override)) {
    out[key] = Object.hasOwn(base, key) ? merge(base[key], override[key]) : clone(override[key]);
  }
  return out;
}

function mergeConfig(base, override) {
  assertSafeKeys(base);
  assertSafeKeys(override);
  return merge(base, override);
}

module.exports = { mergeConfig };

