'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function assertJsonLike(value, path, ancestors) {
  if (value === null || typeof value === 'string' || typeof value === 'boolean') {
    return;
  }
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) {
      throw new TypeError(`non-finite number at ${path}`);
    }
    return;
  }
  if (typeof value !== 'object') {
    throw new TypeError(`unsupported ${typeof value} value at ${path}`);
  }
  if (ancestors.has(value)) {
    throw new TypeError(`circular reference at ${path}`);
  }

  ancestors.add(value);
  if (Array.isArray(value)) {
    for (let i = 0; i < value.length; i++) {
      assertJsonLike(value[i], `${path}[${i}]`, ancestors);
    }
  } else if (isPlainObject(value)) {
    for (const key of Object.getOwnPropertyNames(value)) {
      if (UNSAFE_KEYS.has(key)) {
        throw new TypeError(`unsafe key "${key}" at ${path}`);
      }
    }
    for (const key of Object.keys(value)) {
      assertJsonLike(value[key], `${path}.${key}`, ancestors);
    }
  } else {
    throw new TypeError(`unsupported object type at ${path}`);
  }
  ancestors.delete(value);
}

function deepCopy(value) {
  if (Array.isArray(value)) {
    return value.map(deepCopy);
  }
  if (isPlainObject(value)) {
    const copy = {};
    for (const key of Object.keys(value)) {
      copy[key] = deepCopy(value[key]);
    }
    return copy;
  }
  return value;
}

function mergeValues(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) {
    return deepCopy(override);
  }

  const result = {};
  for (const key of Object.keys(base)) {
    result[key] = Object.hasOwn(override, key)
      ? mergeValues(base[key], override[key])
      : deepCopy(base[key]);
  }
  for (const key of Object.keys(override)) {
    if (!Object.hasOwn(base, key)) {
      result[key] = deepCopy(override[key]);
    }
  }
  return result;
}

function mergeConfig(base, override) {
  assertJsonLike(base, '$base', new Set());
  assertJsonLike(override, '$override', new Set());
  return mergeValues(base, override);
}

module.exports = { mergeConfig };

