'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function copyJson(value, path, ancestors) {
  if (value === null || typeof value === 'string' || typeof value === 'boolean') {
    return value;
  }
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new TypeError(`non-finite number at ${path}`);
    return value;
  }
  if (typeof value !== 'object') {
    throw new TypeError(`unsupported ${typeof value} at ${path}`);
  }

  const isArray = Array.isArray(value);
  if (!isArray && !isPlainObject(value)) {
    throw new TypeError(`unsupported object type at ${path}`);
  }
  if (ancestors.has(value)) throw new TypeError(`circular reference at ${path}`);

  for (const key of Reflect.ownKeys(value)) {
    if (UNSAFE_KEYS.has(key)) throw new TypeError(`unsafe key "${String(key)}" at ${path}`);
  }

  ancestors.add(value);
  try {
    if (isArray) {
      const copy = [];
      for (let i = 0; i < value.length; i++) {
        copy.push(copyJson(value[i], `${path}[${i}]`, ancestors));
      }
      return copy;
    }
    const copy = {};
    for (const key of Object.keys(value)) {
      copy[key] = copyJson(value[key], `${path}.${key}`, ancestors);
    }
    return copy;
  } finally {
    ancestors.delete(value);
  }
}

function mergeCopies(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) return override;
  for (const key of Object.keys(override)) {
    base[key] = Object.prototype.hasOwnProperty.call(base, key)
      ? mergeCopies(base[key], override[key])
      : override[key];
  }
  return base;
}

function mergeConfig(base, override) {
  const baseCopy = copyJson(base, 'base', new Set());
  const overrideCopy = copyJson(override, 'override', new Set());
  return mergeCopies(baseCopy, overrideCopy);
}

