'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function hasOwn(object, key) {
  return Object.prototype.hasOwnProperty.call(object, key);
}

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function assertJsonLike(value, path, ancestors) {
  if (value === null || typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    return;
  }
  if (typeof value !== 'object') {
    throw new TypeError(`${path} has unsupported type ${typeof value}`);
  }
  if (ancestors.has(value)) {
    throw new TypeError(`${path} is a circular reference`);
  }

  const isArray = Array.isArray(value);
  if (!isArray && !isPlainObject(value)) {
    throw new TypeError(`${path} is not a plain object or array`);
  }

  for (const key of Object.getOwnPropertyNames(value)) {
    if (UNSAFE_KEYS.has(key)) {
      throw new TypeError(`${path} contains unsafe key "${key}"`);
    }
  }

  ancestors.add(value);
  for (const key of Object.keys(value)) {
    assertJsonLike(value[key], isArray ? `${path}[${key}]` : `${path}.${key}`, ancestors);
  }
  ancestors.delete(value);
}

function deepCopy(value) {
  if (Array.isArray(value)) {
    return value.map((item) => deepCopy(item));
  }
  if (isPlainObject(value)) {
    const copy = {};
    for (const key of Object.keys(value)) {
      copy[key] = deepCopy(value[key]);
    }
    return copy;
  }
  return value;
}

function mergeValue(baseValue, overrideValue) {
  if (isPlainObject(baseValue) && isPlainObject(overrideValue)) {
    return mergeObjects(baseValue, overrideValue);
  }
  return deepCopy(overrideValue);
}

function mergeObjects(base, override) {
  const result = {};
  for (const key of Object.keys(base)) {
    result[key] = hasOwn(override, key)
      ? mergeValue(base[key], override[key])
      : deepCopy(base[key]);
  }
  for (const key of Object.keys(override)) {
    if (!hasOwn(base, key)) {
      result[key] = deepCopy(override[key]);
    }
  }
  return result;
}

function mergeConfig(base, override) {
  if (!isPlainObject(base)) {
    throw new TypeError('base must be a plain object');
  }
  if (!isPlainObject(override)) {
    throw new TypeError('override must be a plain object');
  }
  assertJsonLike(base, 'base', new Set());
  assertJsonLike(override, 'override', new Set());
  return mergeObjects(base, override);
}

module.exports = { mergeConfig };

