const MAX_SAFE = BigInt(Number.MAX_SAFE_INTEGER);

function splitCents(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError("total must be a nonnegative safe integer");
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError("weights must be a nonempty array");
  }

  const amount = BigInt(total);
  const parts = new Array(weights.length);
  let weightSum = 0n;

  for (let i = 0; i < weights.length; i++) {
    const weight = weights[i];
    if (!Number.isSafeInteger(weight) || weight <= 0) {
      throw new RangeError(`weights[${i}] must be a positive safe integer`);
    }
    const bigWeight = BigInt(weight);
    if (amount * bigWeight > MAX_SAFE) {
      throw new RangeError(`total * weights[${i}] exceeds the safe integer range`);
    }
    weightSum += bigWeight;
    parts[i] = bigWeight;
  }
  if (weightSum > MAX_SAFE) {
    throw new RangeError("sum of weights exceeds the safe integer range");
  }

  const remainders = parts.map((weight) => (amount * weight) % weightSum);
  const shares = parts.map((weight) => (amount * weight) / weightSum);

  const leftover = Number(amount - shares.reduce((acc, share) => acc + share, 0n));
  const byRemainder = shares
    .map((_, index) => index)
    .sort((a, b) => {
      if (remainders[a] !== remainders[b]) {
        return remainders[a] > remainders[b] ? -1 : 1;
      }
      return a - b;
    });

  for (let k = 0; k < leftover; k++) {
    shares[byRemainder[k]] += 1n;
  }

  return shares.map((share) => Number(share));
}

