import re
from datetime import datetime, timezone

_ISO_8601 = re.compile(
    r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})?"
)


def utc_day_start(text):
    if not isinstance(text, str) or not _ISO_8601.fullmatch(text):
        raise ValueError(f"invalid ISO 8601 timestamp: {text!r}")
    candidate = text[:-1] + "+00:00" if text.endswith("Z") else text
    try:
        instant = datetime.fromisoformat(candidate)
    except ValueError:
        raise ValueError(f"invalid ISO 8601 timestamp: {text!r}") from None
    if instant.utcoffset() is None:
        raise ValueError(f"timestamp must include a UTC offset: {text!r}")
    try:
        utc = instant.astimezone(timezone.utc)
    except OverflowError:
        raise ValueError(f"timestamp is out of range: {text!r}") from None
    return datetime(utc.year, utc.month, utc.day, tzinfo=timezone.utc)

