test('compares numerically, not lexically', () => {
  assert.strictEqual(compareVersion('1.10.0', '1.2.9'), 1);
  assert.strictEqual(compareVersion('1.2.9', '1.10.0'), -1);
});

test('compares each component in order', () => {
  assert.strictEqual(compareVersion('2.0.0', '1.99.99'), 1);
  assert.strictEqual(compareVersion('1.2.3', '1.3.0'), -1);
  assert.strictEqual(compareVersion('1.2.4', '1.2.3'), 1);
});

test('returns 0 for equal versions', () => {
  assert.strictEqual(compareVersion('0.0.0', '0.0.0'), 0);
  assert.strictEqual(compareVersion('1.2.3', '1.2.3'), 0);
});

test('compares components beyond Number.MAX_SAFE_INTEGER exactly', () => {
  assert.strictEqual(compareVersion('18446744073709551616.0.0', '18446744073709551615.0.0'), 1);
  assert.strictEqual(compareVersion('0.0.9007199254740993', '0.0.9007199254740992'), 1);
  assert.strictEqual(compareVersion('0.0.9007199254740993', '0.0.9007199254740993'), 0);
  assert.strictEqual(compareVersion('1.99999999999999999999.0', '2.0.0'), -1);
});

test('throws TypeError for malformed strings', () => {
  const malformed = [
    '', '1', '1.2', '1.2.3.4', '1..3', '1.2.', '.1.2',
    '01.2.3', '1.02.3', '1.2.03',
