class Emitter {
  #listeners = new Map();

  on(event, fn) {
    let records = this.#listeners.get(event);
    if (!records) {
      records = [];
      this.#listeners.set(event, records);
    }
    let record = records.find((r) => r.fn === fn);
    if (!record) {
      record = { fn, active: true };
      records.push(record);
    }
    return () => this.#remove(event, record);
  }

  off(event, fn) {
    const records = this.#listeners.get(event);
    const record = records?.find((r) => r.fn === fn);
    if (record) this.#remove(event, record);
  }

  emit(event, value) {
    const records = this.#listeners.get(event);
    if (!records) return;
    const snapshot = records.map((r) => r.fn);
    for (const fn of snapshot) fn(value);
  }

  #remove(event, record) {
    if (!record.active) return;
    record.active = false;
    const records = this.#listeners.get(event);
    records.splice(records.indexOf(record), 1);
    if (records.length === 0) this.#listeners.delete(event);
  }
}

