export type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function mapResult<T, U>(r: Result<T>, fn: (value: T) => U): Result<U> {
  return r.ok ? { ok: true, value: fn(r.value) } : r;
}

export function unwrapOr<T>(r: Result<T>, fallback: T): T {
  return r.ok ? r.value : fallback;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { mapResult, unwrapOr, type Result } from "../src/solution.ts";

const parse = (s: string): Result<number> => {
  const n = Number(s);
  return Number.isNaN(n) ? { ok: false, error: `not a number: ${s}` } : { ok: true, value: n };
};

test("mapResult applies fn on success", () => {
  assert.deepEqual(mapResult(parse("2"), (n) => n * 10), { ok: true, value: 20 });
});

test("mapResult returns failure unchanged and does not call fn", () => {
  let calls = 0;
  const failure: Result<number> = { ok: false, error: "boom" };
  const r = mapResult(failure, (n: number) => {
    calls++;
    return n * 10;
  });
  assert.equal(calls, 0);
  assert.equal(r, failure);
});

test("mapResult propagates exceptions from fn", () => {
  assert.throws(
    () =>
      mapResult({ ok: true, value: 1 }, () => {
        throw new Error("bad");
      }),
    /bad/,
  );
});

test("unwrapOr returns value on success", () => {
  assert.equal(unwrapOr(parse("3"), 0), 3);
});

test("unwrapOr returns fallback on failure", () => {
  assert.equal(unwrapOr(parse("x"), 0), 0);
});

