export type Result<T> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly error: string };

export function mapResult<T, U>(r: Result<T>, fn: (value: T) => U): Result<U> {
  if (r.ok) {
    return { ok: true, value: fn(r.value) };
  }
  return r;
}

export function unwrapOr<T>(r: Result<T>, fallback: T): T {
  return r.ok ? r.value : fallback;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { mapResult, unwrapOr, type Result } from "../src/solution.ts";

const ok = <T>(value: T): Result<T> => ({ ok: true, value });
const fail = <T>(error: string): Result<T> => ({ ok: false, error });

const parsed: Result<number> = ok(21);
const doubled: Result<number> = mapResult(parsed, (n) => n * 2);
const described: Result<string> = mapResult(doubled, (n) => `value=${n}`);
const failedParse: Result<number> = fail("not a number");
const lengthOfFailure: Result<number> = mapResult(failedParse, (n) => n + 1);

test("examples type-check and compute expected values", () => {
  assert.deepEqual(doubled, { ok: true, value: 42 });
  assert.deepEqual(described, { ok: true, value: "value=42" });
  assert.deepEqual(lengthOfFailure, { ok: false, error: "not a number" });
});

test("mapResult applies fn to the success value", () => {
  assert.deepEqual(mapResult(ok(2), (n) => n * 3), { ok: true, value: 6 });
});

test("mapResult can change the value type", () => {
  const parsedNumber = mapResult(ok("42"), (s) => Number(s));
  assert.deepEqual(parsedNumber, { ok: true, value: 42 });
});

test("mapResult does not call fn on failure", () => {
  let calls = 0;
  const input = fail<number>("boom");
  const output = mapResult(input, (n) => {
    calls++;
    return n;
  });
  assert.equal(calls, 0);
  assert.strictEqual(output, input);
});

test("mapResult returns the failure unchanged", () => {
  const input = fail<number>("boom");
  assert.deepEqual(mapResult(input, (n) => n + 1), { ok: false, error: "boom" });
});

test("mapResult lets exceptions from fn propagate", () => {
  assert.throws(
    () =>
      mapResult(ok(1), () => {
        throw new Error("fn failed");
      }),
    { message: "fn failed" },
  );
});

test("mapResult does not run a throwing fn on failure", () => {
  const input = fail<number>("boom");
  assert.doesNotThrow(() =>
    mapResult(input, () => {
      throw new Error("should not run");
    }),
  );
});

test("unwrapOr returns the value on success", () => {
  assert.equal(unwrapOr(ok(7), 0), 7);
});

test("unwrapOr returns the fallback on failure", () => {
  assert.equal(unwrapOr(fail<number>("boom"), 0), 0);
});

test("unwrapOr works with mapResult chains", () => {
  const result = mapResult(fail<number>("bad"), (n) => n * 10);
  assert.equal(unwrapOr(result, -1), -1);
});

