import { test } from "node:test";
import assert from "node:assert/strict";
import { mapResult, unwrapOr, type Result } from "../src/solution.ts";

const ok = <T>(value: T): Result<T> => ({ ok: true, value });
const fail = <T>(error: string): Result<T> => ({ ok: false, error });

const parseInteger = (s: string): Result<number> => {
  const n = Number(s);
  return Number.isInteger(n) ? ok(n) : fail(`not an integer: ${s}`);
};

test("mapResult applies fn to a success value", () => {
  const r: Result<number> = ok(2);
  const out: Result<string> = mapResult(r, (x) => `n=${x}`);
  assert.deepEqual(out, { ok: true, value: "n=2" });
});

test("mapResult does not call fn on failure and returns the failure unchanged", () => {
  let calls = 0;
  const r: Result<number> = fail("boom");
  const out = mapResult(r, (x: number) => {
    calls += 1;
    return x * 2;
  });
  assert.equal(calls, 0);
  assert.strictEqual(out, r);
});

test("mapResult chains without calling later fns after a failure", () => {
  let calls = 0;
  const counted = (x: number): number => {
    calls += 1;
    return x + 1;
  };
  const out = mapResult(mapResult(parseInteger("abc"), counted), counted);
  assert.equal(calls, 0);
  assert.deepEqual(out, { ok: false, error: "not an integer: abc" });
});

test("mapResult chains success values through each fn", () => {
  const out = mapResult(mapResult(parseInteger("2"), (x) => x + 1), (x) => x * 10);
  assert.deepEqual(out, { ok: true, value: 30 });
});

test("mapResult propagates exceptions thrown by fn", () => {
  const r: Result<number> = ok(1);
  assert.throws(
    () =>
