  const values = [0, 1, 2, 3];
  const targets = [-1, 0, 0.5, 1, 1.5, 2, 2.5, 3, 3.5];
  for (let n = 0; n <= 4; n++) {
    const arrays = [[]];
    for (let k = 0; k < n; k++) {
      const next = [];
      for (const a of arrays) if (a.length === k) for (const v of values) next.push([...a, v]);
      arrays.push(...next);
    }
    for (const a of arrays) {
      if (a.length !== n) continue;
      const sorted = [...a].sort((x, y) => x - y);
      for (const t of targets) {
